script:
frappe.ui.form.on('HD Ticket', {
    refresh(frm) {
        if (frm.is_new()) return;

        // Only the ticket's holder - and Amal, Walid, admin@sabre-egy.com -
        // may create the escalation sub-task.
        // sabre_can_edit is declared in 'HD Ticket - Lock Fields To Holder'.
        if (typeof sabre_can_edit !== 'function' || sabre_can_edit(frm)) {
            frm.add_custom_button('Create a new sub-task', () => {
                frappe.new_doc('Task', {
                    subject: frm.doc.subject,
                    custom_ticket: frm.doc.name,
                    description: 'Linked to Ticket: ' + frm.doc.name
                });
            });
        }

        // Fetch linked tasks and display them in the dashboard
        frappe.db.get_list('Task', {
            filters: { custom_ticket: frm.doc.name, status: ['!=', 'Cancelled'] },
            fields: ['name', 'subject', 'status', 'custom_assign_to'] // الحقل المطلوب جلبه
        }).then(tasks => {
            if (tasks.length > 0) {
                let html = '<table class="table table-bordered table-sm" style="margin-top:8px">';
                html += '<thead><tr><th>Task</th><th>Subject</th><th>Status</th><th>Escalate To</th></tr></thead><tbody>';
                tasks.forEach(t => {
                    let escalatedUser = t.custom_assign_to || '-';
                    html += `<tr>
                        <td><a href="/app/task/${t.name}" target="_blank">${t.name}</a></td>
                        <td>${t.subject || ''}</td>
                        <td>${t.status || ''}</td>
                        <td>${escalatedUser}</td>
                    </tr>`;
                });
                html += '</tbody></table>';
                frm.dashboard.add_section(html, 'Linked Tasks');
            }
        });
    }
});
